# -*- coding: utf-8 -*-
"""Trade close for MT4 (replaces OANDA)"""

import sys
import os

# Add parent directory to path for imports
sys.path.insert(0, os.path.dirname(os.path.dirname(os.path.abspath(__file__))))

try:
    from baserequest import BaseRequest
except ImportError:
    # Fallback for when running as script
    class BaseRequest:
        def __init__(self):
            self._data = {}
        
        @property
        def data(self):
            return self._data


class TradeCloseRequest(BaseRequest):
    """create a TradeCloseRequest.

    TradeCloseRequest is used to build the body to close a trade.
    The body can be used to pass to the TradeClose endpoint.
    
    For MT4, this now serves as a data structure for closing positions.
    Actual closing is handled via the MT4 client's close_position method.
    """

    def __init__(self, units="ALL"):
        """
        Instantiate a TradeCloseRequest.

        Parameters
        ----------

        units : integer (optional)
            the number of units to close. Default it is set to "ALL".

        Example
        -------

        >>> from mt4_trade_requests import TradeCloseRequest
        >>>
        >>> # Create a trade close request
        >>> close_req = TradeCloseRequest(units=10000)
        >>> print(close_req.data)
        {'units': '10000'}
        >>>
        >>> # For MT4, use the MT4 client to close positions:
        >>> from mt4_price_provider import get_mt4_prices
        >>> mt4 = get_mt4_prices()
        >>> result = mt4.close_position(ticket_id)
        """
        super(TradeCloseRequest, self).__init__()

        # by default for a TradeClose no parameters are required
        if units:
            if units != "ALL":
                self._data.update({"units": "{:d}".format(int(units))})
            else:
                self._data.update({"units": "ALL"})


# ============ MT4 Trade Close Helper ============

class MT4TradeCloseHelper:
    """
    Helper class to close trades in MT4 (replaces OANDA TradeClose)
    """
    
    def __init__(self):
        from mt4_price_provider import get_mt4_prices
        self.mt4 = get_mt4_prices()
    
    def close_trade(self, trade_id, units="ALL"):
        """
        Close a trade in MT4
        
        Parameters
        ----------
        trade_id : int
            The MT4 ticket number of the trade to close
        units : str or int
            Number of units to close (default "ALL")
        
        Returns
        -------
        dict
            Result of the close operation
        """
        try:
            result = self.mt4.close_position(trade_id)
            return result
        except Exception as e:
            return {'success': False, 'error': str(e)}
    
    def close_all_positions(self, symbol=None):
        """
        Close all open positions, optionally filtered by symbol
        
        Parameters
        ----------
        symbol : str, optional
            MT4 symbol (e.g., 'EURUSD') to close only positions for that symbol
        
        Returns
        -------
        list
            List of results for each closed position
        """
        positions = self.mt4.get_positions()
        
        if not positions.get('success'):
            return []
        
        results = []
        for pos in positions.get('positions', []):
            if symbol is None or pos.get('symbol') == symbol:
                result = self.mt4.close_position(pos.get('ticket'))
                results.append(result)
        
        return results
    
    def get_open_positions(self):
        """
        Get all open positions
        
        Returns
        -------
        list
            List of open positions
        """
        result = self.mt4.get_positions()
        return result.get('positions', []) if result.get('success') else []


# For backward compatibility with OANDA-style code
def create_trade_close_request(units="ALL"):
    """
    Create a trade close request (compatible with OANDA interface)
    
    Parameters
    ----------
    units : str or int
        Number of units to close
    
    Returns
    -------
    TradeCloseRequest
        Trade close request object
    """
    return TradeCloseRequest(units=units)


# ============ Test ============

if __name__ == "__main__":
    print("=" * 50)
    print("Testing MT4 Trade Close")
    print("=" * 50)
    
    # Test TradeCloseRequest
    close_req = TradeCloseRequest(units=10000)
    print("\nTradeCloseRequest (10000 units):", close_req.data)
    
    close_req_all = TradeCloseRequest(units="ALL")
    print("TradeCloseRequest (ALL units):", close_req_all.data)
    
    # Test MT4 helper
    print("\nTesting MT4 Trade Close Helper...")
    helper = MT4TradeCloseHelper()
    
    # Check connection
    if helper.mt4.test_connection():
        print("✅ MT4 connected")
        
        # Get open positions
        positions = helper.get_open_positions()
        print(f"Open positions: {len(positions)}")
        
        # Close first position if any
        if positions:
            result = helper.close_trade(positions[0].get('ticket'))
            print(f"Close result: {result}")
    else:
        print("⚠️ MT4 not connected")
    
    print("\n✅ MT4 trade close ready")
